package com.vehiclerental.mak.auth.service;
import com.vehiclerental.mak.auth.entity.*;import com.vehiclerental.mak.auth.repository.*;import com.vehiclerental.mak.common.exception.ApiException;import com.vehiclerental.mak.notifications.email.service.EmailService;
import java.util.*;import java.time.Instant;import java.security.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;
@Service
public class InvitationService{
 private final InvitationRepository invitations;private final AccountRepository accounts;private final AuthControlRepository controls;private final AuthAuditRepository audits;private final RoleService roles;private final EmailService emails;private final boolean mailEnabled;private final String frontend;
 public InvitationService(InvitationRepository invitations,AccountRepository accounts,AuthControlRepository controls,AuthAuditRepository audits,RoleService roles,EmailService emails,@Value("${app.mail.enabled:false}") boolean mailEnabled,@Value("${app.auth.frontend-url:http://localhost:5173}") String frontend){this.invitations=invitations;this.accounts=accounts;this.controls=controls;this.audits=audits;this.roles=roles;this.emails=emails;this.mailEnabled=mailEnabled;this.frontend=frontend;}
 @Transactional(readOnly=true) public Map<String,Object> list(){return Map.of("emailEnabled",mailEnabled,"invitations",invitations.findAllByOrderByCreatedAtDesc().stream().map(this::response).toList());}
 @Transactional public Map<String,Object> invite(Map<String,Object> data,long actor){controls.lockControl().orElseThrow();if(!mailEnabled)throw bad("Configure email delivery before sending invitations.");if(data.get("roleId")!=null&&!(data.get("roleId") instanceof Number))throw bad("Choose a valid role.");String email=text(data.get("email")).toLowerCase(Locale.ROOT),name=text(data.get("name"));if(name.isBlank()||name.length()>200||email.length()>254||!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw bad("Enter a name and valid work email.");if(accounts.findByEmail(email).isPresent())throw bad("An account already uses this email. Manage it in Members.");if(invitations.findAll().stream().anyMatch(i->i.getEmail().equals(email)&&"Pending".equals(i.getStatus())&&i.getExpiresAt().isAfter(Instant.now())))throw bad("A pending invitation already exists for this email.");var invite=new Invitation();invite.setName(name);invite.setEmail(email);invite.setRole(data.get("roleId")==null?text(data.get("role")):"Viewer");invite.setCustomRoleId(data.get("roleId") instanceof Number n?n.longValue():null);roles.validateAssignment(invite.getRole(),invite.getCustomRoleId());invite.setStatus("Pending");invite.setCreatedAt(Instant.now());invite.setCreatedBy(actor);String token=token(invite);invitations.saveAndFlush(invite);deliver(invite,token);audit(invite,actor,"USER_INVITED");return response(invite);}
 @Transactional public Map<String,Object> update(long id,String action,long actor){controls.lockControl().orElseThrow();var invite=invitations.lockById(id).orElseThrow(()->bad("Invitation not found."));if(!"Pending".equals(invite.getStatus()))throw bad("Only pending invitations can be changed.");if("revoke".equals(action)){invite.setStatus("Revoked");audit(invite,actor,"INVITATION_REVOKED");}else if("resend".equals(action)){if(!mailEnabled)throw bad("Configure email delivery before resending.");deliver(invite,token(invite));audit(invite,actor,"INVITATION_RESENT");}else throw bad("Unknown invitation action.");return response(invite);}
 @Transactional(readOnly=true) public Map<String,Object> preview(String token){var i=valid(token);return Map.of("name",i.getName(),"email",i.getEmail(),"role",roles.name(i.getRole(),i.getCustomRoleId()),"expiresAt",i.getExpiresAt());}
 public void accept(String token,String email,Account account){var i=valid(token);if(!i.getEmail().equals(email))throw bad("Use the invited email address.");roles.validateAssignment(i.getRole(),i.getCustomRoleId());i.setStatus("Accepted");account.setRole(i.getRole());account.setCustomRoleId(i.getCustomRoleId());account.setStatus("Active");}
 private Invitation valid(String token){if(token==null||token.length()>200)throw bad("Invalid invitation link.");return invitations.findByTokenHash(hash(token)).filter(i->"Pending".equals(i.getStatus())&&i.getExpiresAt().isAfter(Instant.now())).orElseThrow(()->bad("Invitation is expired, revoked or already accepted."));}
 private String token(Invitation i){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);i.setTokenHash(hash(token));i.setExpiresAt(Instant.now().plusSeconds(7*86400));return token;}
 private void deliver(Invitation i,String token){emails.staffInvitation(i.getId(),i.getEmail(),i.getName(),roles.name(i.getRole(),i.getCustomRoleId()),frontend.replaceAll("/+$","")+"/#/sign-up?invitation="+token,i.getExpiresAt());}
 private Map<String,Object> response(Invitation i){var result=new LinkedHashMap<String,Object>();result.put("id",i.getId());result.put("name",i.getName());result.put("email",i.getEmail());result.put("role",roles.name(i.getRole(),i.getCustomRoleId()));result.put("status","Pending".equals(i.getStatus())&&i.getExpiresAt().isBefore(Instant.now())?"Expired":i.getStatus());result.put("createdAt",i.getCreatedAt());result.put("expiresAt",i.getExpiresAt());return result;}
 private void audit(Invitation i,long actor,String event){var a=new AuthAudit();a.setActorId(actor);a.setEvent(event);a.setSummary(i.getEmail()+"; "+roles.name(i.getRole(),i.getCustomRoleId()));a.setCreatedAt(Instant.now());audits.save(a);}
 private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private String text(Object v){return v==null?"":v.toString().trim();}private ApiException bad(String s){return new ApiException(HttpStatus.BAD_REQUEST,s);}
}
